import org.slf4j.LoggerFactory
def logger = LoggerFactory.getLogger("MarketplaceServices")

logger.info("Installing 3rd-Party Plugin '${pluginId}' for Tenant '${tenantId}'")

// MOCK PLUGIN INSTALLATION LOGIC
// In production, this would validate the apiKey against the 3rd-party service,
// generate OAuth tokens if necessary, and create a TenantPluginConfig record.

if (!apiKey && pluginId == "salesforce-sync") {
    ec.message.addError("API Key is required to install the Salesforce Sync plugin.")
    return
}

logger.info("Plugin '${pluginId}' successfully provisioned and activated!")
ec.message.addMessage("Successfully installed the ${pluginId} plugin.")
